-- ComfyClub — seeded starter reviews (matches the design prototype).
-- Deterministic per product SKU. All approved + text-only. Safe to re-run:
-- it clears previously-seeded starter reviews first (those with no admin_reply
-- and a name from the starter set) — real customer reviews are untouched.
BEGIN;

-- Remove only prior STARTER seeds (idempotent re-runs); keep real submissions.
DELETE FROM reviews r
USING products p
WHERE r.product_id = p.id
  AND r.status = 'approved'
  AND r.admin_reply IS NULL
  AND r.image_url IS NULL
  AND r.text IN ('Excellent craftsmanship.', 'Stunning piece, love it!', 'Very comfortable and looks exactly like the photos. Delivery was on time.', 'Great quality', 'Good value for money. Happy with the purchase overall.', 'Superb', 'Beautiful design and very sturdy. Our guests always compliment it.', 'Perfect for our drawing room', 'Nice quality. Took a bit longer to deliver but worth the wait.', 'Absolutely love it', 'Premium feel. You can tell this is handmade with care.', 'Comfortable and well built', 'Ordered two for our guest room. They look amazing together.');


-- Refresh the rating aggregates used by the storefront.
SELECT refresh_product_ratings();

COMMIT;
